"""Bundled default skills.

These skills are merged into every project at bootstrap time via the
skill catalog (defaults first; project skills take precedence on duplicate IDs).
"""

from rasa.mantle.skills.catalog import load_default_skill_catalog

# Built-in default skill IDs and their compiled entry target IDs.
DEFAULT_COMPLETED = "default_completed"
DEFAULT_COMPLETED_TARGET_ID = f"{DEFAULT_COMPLETED}__main"
# Compatibility alias — keep importable while callers migrate to TARGET_ID.
DEFAULT_COMPLETED_FLOW_ID = DEFAULT_COMPLETED_TARGET_ID

DEFAULT_CUSTOMER_SATISFACTION = "default_customer_satisfaction"
DEFAULT_CUSTOMER_SATISFACTION_FLOW_ID = f"{DEFAULT_CUSTOMER_SATISFACTION}__main"

DEFAULT_CONTINUE_INTERRUPTED = "default_continue_interrupted"
DEFAULT_CONTINUE_INTERRUPTED_FLOW_ID = f"{DEFAULT_CONTINUE_INTERRUPTED}__main"
# Public memory entry collected by ``default_continue_interrupted`` and read
# by the executor after that skill completes (resume vs dismiss).
WANTS_TO_RESUME_ENTRY = "wants_to_resume"
# Set when the skill activates: human-readable name of the paused task to resume.
INTERRUPTED_TASK_NAME_ENTRY = "interrupted_task_name"
# Generic label used when the display name cannot be written or read.
INTERRUPTED_TASK_NAME_FALLBACK = "your previous request"

DEFAULT_UNSUPPORTED_REQUEST_HANDLER = "default_unsupported_request_handler"
DEFAULT_UNSUPPORTED_REQUEST_HANDLER_FLOW_ID = (
    f"{DEFAULT_UNSUPPORTED_REQUEST_HANDLER}__main"
)

# Public memory entry the ``cannot_help`` dispatch seeds on the decline skill so
# its gate step can pick the matching decline; and its two valid values. Both are
# out-of-scope requests — the distinction is whether they are in the agent's
# domain or outside it.
REQUEST_TYPE_ENTRY = "request_type"
REQUEST_TYPE_IN_DOMAIN_OUT_OF_SCOPE = "in_domain_out_of_scope"
REQUEST_TYPE_OUT_OF_DOMAIN_OUT_OF_SCOPE = "out_of_domain_out_of_scope"

DEFAULT_SESSION_START = "default_session_start"
DEFAULT_SESSION_START_FLOW_ID = f"{DEFAULT_SESSION_START}__main"

DEFAULT_SILENCE_TIMEOUT = "default_silence_timeout"
